# 1. 重写 _updateRain：逐个到达恢复 + 全体完成兜底清除
old_update = '''  /** 每帧更新粒子状态：粒子到达后立即恢复其对应文字 */
  private _updateRain(now: number): void {
    const remaining: RainParticle[] = [];
    for (const p of this._rainParticles) {
      if (now < p.startTime + p.duration) {
        remaining.push(p);
      } else {
        // 粒子到达，清除它对应的 _rainSkipText 标记
        if (p._boxId) {
          this._clearSkipById(this._root, p._boxId);
        }
      }
    }
    this._rainParticles = remaining;
  }

  /** 按 id 清除 _rainSkipText 标记 */
  private _clearSkipById(box: Box | null, id: string): void {
    if (!box) return;
    if (box.id === id) {
      delete (box as any)._rainSkipText;
      return;
    }
    for (const child of box.children) {
      this._clearSkipById(child, id);
    }
  }'''

new_update = '''  /** 每帧更新粒子状态：逐个到达恢复文字 + 全体完成兜底 */
  private _updateRain(now: number): void {
    const hadParticles = this._rainParticles.length > 0;
    const remaining: RainParticle[] = [];
    for (const p of this._rainParticles) {
      if (now < p.startTime + p.duration) {
        remaining.push(p);
      } else if (p._boxId) {
        this._clearSkipById(this._root, p._boxId);
      }
    }
    this._rainParticles = remaining;

    // 全体完成时兜底全局清除
    if (hadParticles && this._rainParticles.length === 0 && this._root) {
      this._clearAllSkip(this._root);
    }
  }

  private _clearSkipById(box: Box | null, id: string): void {
    if (!box) return;
    if (box.id === id) { delete (box as any)._rainSkipText; return; }
    for (const child of box.children) this._clearSkipById(child, id);
  }

  private _clearAllSkip(box: Box): void {
    delete (box as any)._rainSkipText;
    for (const child of box.children) this._clearAllSkip(child);
  }'''

content = content.replace(old_update, new_update)

# 2. 位置偏移修复：粒子 targetX/targetY 使用绝对坐标
